import json,sys
sys.path.insert(0,'.')
from phase1.schema import compute_tag, compute_confidence, validate_v2
AG='targeted3-H'
def load(c): return json.load(open(f'phase1/evidence/{c}.json'))
def save(c,d):
    d['tag'],_=compute_tag(d['elections']); d['confidence']=compute_confidence(d)
    validate_v2(d); json.dump(d,open(f'phase1/evidence/{c}.json','w'),indent=2,ensure_ascii=False); open(f'phase1/evidence/{c}.json','a').write('\n')
    print(c,d['tag'],d['confidence'])
def note(d,t): d['notes']=d['notes'].rstrip()+' Targeted pass 3 2026-10-02 (targeted3-H): '+t
def chk3(c): return f"Check 3: the Wayback harvest (phase1/wayback_snapshots/{c}/index.json on wayback-data) found no election-night captures for this election; no targeted archive or sweep folder exists for this county."

